package com.company.tpm.notification;import java.util.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService{private final JdbcClient db;public NotificationService(JdbcClient d){db=d;}@Transactional public boolean enqueue(UUID recipient,String channel,String type,String logicalId,String payload){return db.sql("insert into notification_deliveries(recipient_id,channel,notification_type,logical_id,payload,status) values(:r,:c,:t,:l,cast(:p as jsonb),'PENDING') on conflict(logical_id,channel,recipient_id) do nothing").param("r",recipient).param("c",channel).param("t",type).param("l",logicalId).param("p",payload).update()==1;}}
